import {Sequence, useVideoConfig} from "remotion";
import Intro from "./chapters/intro";
import Ending from "./chapters/ending";
export default function Animation() {
  // Sequence supplies chapter-local frames; the composition keeps one rational timebase.
  const {durationInFrames} = useVideoConfig();
  const split = Math.floor(durationInFrames / 2);
  return <><Sequence durationInFrames={split}><Intro /></Sequence>
    <Sequence from={split}><Ending /></Sequence></>;
}
